138	/// The video group. `size` is the source's pixel size when it is known, so
139	/// a crop can be checked against the thing being cropped.
140	pub(crate) fn check_video(props: &VideoProps, size: Option<(f64, f64)>) -> Result<(), String> {
141	    finite("video.x", props.x)?;
142	    finite("video.y", props.y)?;
143	    in_range("video.scale", props.scale, SCALE_MIN, SCALE_MAX)?;
144	    finite("video.rotation", props.rotation)?;
145	    in_range("video.opacity", props.opacity, 0.0, 1.0)?;
146	    at_least("video.corner_radius", props.corner_radius, 0.0)?;
147	    at_least("video.crop.l", props.crop.l, 0.0)?;
148	    at_least("video.crop.t", props.crop.t, 0.0)?;
149	    at_least("video.crop.r", props.crop.r, 0.0)?;
150	    at_least("video.crop.b", props.crop.b, 0.0)?;
151	    // Opposite edges must leave something behind: a crop that meets or
152	    // crosses is an empty rectangle, which no renderer can draw.
153	    if let Some((width, height)) = size {
154	        let horizontal = props.crop.l + props.crop.r;
155	        if horizontal >= width {
156	            return Err(format!(
157	                "video.crop l + r must be less than the source width {width}, not {horizontal}"
158	            ));
159	        }
160	        let vertical = props.crop.t + props.crop.b;
161	        if vertical >= height {
162	            return Err(format!(
163	                "video.crop t + b must be less than the source height {height}, not {vertical}"
164	            ));
165	        }
166	    }
167	    // Motion (format version 8). The two edge values are DURATIONS, so 0 is
168	    // legal — it means that end of the clip does not move — and a negative
169	    // one is a sign mistake, not a request to run the preset backwards;
170	    // `text.animation`'s arm below is the precedent. These ticks are not
171	    // snapped HERE, and since D1·2 that is an order rather than an
172	    // exemption: `edit_props.rs`'s `snap_motion` puts them on the frame
173	    // grid AFTER this check, so a refusal names the number the caller sent
174	    // rather than one the door rounded it to. `amount` is a fraction of the
175	    // preset's own range, so 0 is the identity and 1 the full strength.
176	    // `period` is the one value with no meaningful zero: it is a divisor in
177	    // every `during` formula, so one tick is the floor and the message says
178	    // so rather than naming a range (the snap's own floor is a FRAME, for
179	    // the same reason one step further on). The two KINDS need no check —
180	    // serde refuses an unknown variant on the way in, which is what closing
181	    // both enums bought (`model_motion.rs`).
182	    if let Some(motion) = &props.motion {
183	        if let Some(edge) = &motion.r#in {
184	            ticks_positive_or_zero("video.motion.in.duration", edge.duration)?;
185	        }
186	        if let Some(edge) = &motion.out {
187	            ticks_positive_or_zero("video.motion.out.duration", edge.duration)?;
188	        }
189	        if let Some(during) = &motion.during {
190	            in_range("video.motion.during.amount", during.amount, 0.0, 1.0)?;
191	            if during.period < 1 {
192	                return Err(format!(
193	                    "video.motion.during.period must be at least one tick, not {}",
194	                    during.period
195	                ));
196	            }
197	        }
198	    }
199	    if let Some(shadow) = &props.shadow {
200	        color_ok("video.shadow.color", &shadow.color)?;
201	        in_range("video.shadow.opacity", shadow.opacity, 0.0, 1.0)?;
202	        at_least("video.shadow.blur", shadow.blur, 0.0)?;
203	        finite("video.shadow.angle", shadow.angle)?;
204	        at_least("video.shadow.distance", shadow.distance, 0.0)?;
205	    }
206	    // The color controls are offsets from neutral, not absolute levels, so
207	    // any finite value is meaningful; the UI's sliders bound them.
208	    finite("video.color.brightness", props.color.brightness)?;
209	    finite("video.color.contrast", props.color.contrast)?;
